// Owned ROM; generated by scripts/physics/generate_sine.py. One shared read port.
// MEM_FILE is relative to the simulation/project run directory unless overridden.
module q_sincos #(parameter MEM_FILE="rtl/physics/q_sine_q16.mem")(
 input wire clk,input wire rst,input wire req_valid,output wire req_ready,
 input wire [31:0] req_phase,output reg rsp_valid,input wire rsp_ready,
 output reg signed [17:0] rsp_sin_q16,output reg signed [17:0] rsp_cos_q16
);
 `include "q_numeric_functions.vh"
 (* rom_style="block" *) reg signed [17:0] sine[0:4095];
 initial $readmemh(MEM_FILE,sine);
 reg [2:0] state;
 reg [11:0] index;
 reg [19:0] fraction;
 reg signed [17:0] s0,s1,c0,c1;
 reg [11:0] address;
 reg signed [17:0] sample;
 wire signed [18:0] ds={s1[17],s1}-{s0[17],s0};
 wire signed [18:0] dc={c1[17],c1}-{c0[17],c0};
 wire signed [39:0] ps=ds*$signed({1'b0,fraction});
 wire signed [39:0] pc=dc*$signed({1'b0,fraction});
 reg signed [39:0] product_s,product_c;
 reg signed [127:0] temp;
 assign req_ready=state==0 && !rsp_valid;
 // A single synchronous ROM port; the address schedule includes read latency.
 always @* begin
  case(state)
   1: address=index;
   2: address=index+12'd1;
   3: address=index+12'd1024;
   default: address=index+12'd1025;
  endcase
 end
 always @(posedge clk) sample<=sine[address];
 always @(posedge clk) begin
  if(rst) begin state<=0;rsp_valid<=0;rsp_sin_q16<=0;rsp_cos_q16<=0;index<=0;fraction<=0;s0<=0;s1<=0;c0<=0;c1<=0;end
  else begin
   if(rsp_valid && rsp_ready) rsp_valid<=0;
   if(req_valid && req_ready) begin index<=req_phase[31:20];fraction<=req_phase[19:0];state<=1;end
   else case(state)
    1:state<=2;
    2:begin s0<=sample;state<=3;end
    3:begin s1<=sample;state<=4;end
    4:begin c0<=sample;state<=5;end
    5:begin c1<=sample;state<=6;end
    6:begin product_s<=ps;product_c<=pc;state<=7;end
    7:begin
     temp=q_rne_shift(({{88{product_s[39]}},product_s}+($signed(s0)*128'sd1048576)),20);rsp_sin_q16<=temp[17:0];
     temp=q_rne_shift(({{88{product_c[39]}},product_c}+($signed(c0)*128'sd1048576)),20);rsp_cos_q16<=temp[17:0];
     rsp_valid<=1;state<=0;
    end
    default:state<=0;
   endcase
  end
 end
endmodule
